import{_ as i,o as s,c as a,a2 as n}from"./chunks/framework.BTLSZHNB.js";const k=JSON.parse('{"title":"0010 — Exact Interface contracts and typed Bindings","description":"","frontmatter":{},"headers":[],"relativePath":"spec/decisions/0010-exact-interface-and-binding-contracts.md","filePath":"spec/decisions/0010-exact-interface-and-binding-contracts.md"}'),t={name:"spec/decisions/0010-exact-interface-and-binding-contracts.md"};function o(r,e,c,l,d,h){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="_0010-—-exact-interface-contracts-and-typed-bindings" tabindex="-1">0010 — Exact Interface contracts and typed Bindings <a class="header-anchor" href="#_0010-—-exact-interface-contracts-and-typed-bindings" aria-label="Permalink to &quot;0010 — Exact Interface contracts and typed Bindings&quot;">​</a></h1><ul><li>Status: accepted</li><li>Date: 2026-08-06</li><li>Owners: Takoform maintainers</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Current Interface declarations are open <code>(name, version, operations)</code> descriptors. They do not fix request/response types, errors, consistency, pagination, or retry, so two hosts can expose the &quot;same&quot; interface with incompatible behavior.</p><p>Resource-to-resource connections are generic:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;resource&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;KeyValueStore/cache&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;permissions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;read&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;write&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;projection&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;keyvalue.binding.v1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Free <code>permissions</code> and <code>projection</code> tokens delegate the meaning of the connection to each host. The proven model — a binding that grants a capability and a concrete runtime API together, without exposing credentials — cannot be expressed, verified, or held stable this way.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><h3 id="exact-interface-contracts" tabindex="-1">Exact Interface contracts <a class="header-anchor" href="#exact-interface-contracts" aria-label="Permalink to &quot;Exact Interface contracts&quot;">​</a></h3><p>An Interface becomes an independently published, digest-bound contract:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;apiVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;interfaces.takoform.com/v1alpha1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;edge.kv&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schemaDigest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sha256:...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>An Interface Definition fixes operations with input/output schemas, a closed error vocabulary, consistency and pagination semantics, portable minimum limits, and data-only behavior fixtures (conformance traces such as put-then-get), not just a name and an operation list. Interface Packages follow the Form Package rules: one package, one definition, exact digest, data-only payloads, positive and negative fixtures.</p><h3 id="typed-bindings" tabindex="-1">Typed Bindings <a class="header-anchor" href="#typed-bindings" aria-label="Permalink to &quot;Typed Bindings&quot;">​</a></h3><p>Generic connections, <code>permissions</code>, and <code>projection</code> are removed from the new line. A Binding is its own digest-bound contract:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;apiVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;bindings.takoform.com/v1alpha1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;module-worker.edge-kv&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schemaDigest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sha256:...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>A Binding Definition fixes the source Form role, the target Interface, the runtime API projected into the consumer, the allowed target Forms, optional access modes, lifecycle, and the binding-name grammar. A binding grants capability and API together and never exposes credentials or secret values to the consumer. Worker-family binding names use the JavaScript identifier grammar <code>^[A-Za-z_$][A-Za-z0-9_$]*$</code>.</p><p>Outward capability use (KV, buckets, databases, queues, services) is a Binding held by a revision resource. Inward invocation (routes, custom domains, cron, queue consumption) is an attachment resource, never a binding.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Form Definitions reference Interfaces and Bindings by exact ref; the old <code>(name, version, operations)</code> projection stays only in the retained v1alpha2 lane docs.</li><li>The provider exposes typed binding blocks (<code>kv_binding</code>, <code>bucket_binding</code>, <code>sqlite_binding</code>, <code>queue_producer_binding</code>, <code>service_binding</code>) instead of a generic <code>connections</code> map.</li><li>New public schema identities are minted for interface-ref, interface-definition, binding-ref, and binding-definition documents.</li><li>Behavior fixtures make interface conformance testable beyond shape validation; location-dependent properties (for example eventual-consistency convergence) are explicitly out of the deterministic fixture scope.</li></ul><h2 id="rejected-alternatives" tabindex="-1">Rejected alternatives <a class="header-anchor" href="#rejected-alternatives" aria-label="Permalink to &quot;Rejected alternatives&quot;">​</a></h2><ul><li><strong>Harden the generic connection with more token vocabularies.</strong> Rejected because closed token lists on a generic surface still cannot bind an actual runtime API or error contract; every new pair of resources would grow the central vocabulary.</li><li><strong>Define bindings inside each Form Definition only.</strong> Rejected because the same binding shape (worker → KV) must stay identical across families and hosts; an independent digest-bound contract keeps it single-sourced.</li><li><strong>Executable conformance suites inside packages.</strong> Rejected because packages are data-only by trust policy; behavior fixtures stay declarative traces executed by the verifier.</li></ul>`,21)])])}const u=i(t,[["render",o]]);export{k as __pageData,u as default};
